// HasRegistration applies the HasEdge predicate on the "registration" edge.
func HasRegistration() predicate.ContestRegistrationTransition {
	return predicate.ContestRegistrationTransition(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RegistrationTable, RegistrationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRegistrationWith applies the HasEdge predicate on the "registration" edge with a given conditions (other predicates).
func HasRegistrationWith(preds ...predicate.ContestRegistration) predicate.ContestRegistrationTransition {
	return predicate.ContestRegistrationTransition(func(s *sql.Selector) {
		step := newRegistrationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContestRegistrationTransition) predicate.ContestRegistrationTransition {
	return predicate.ContestRegistrationTransition(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContestRegistrationTransition) predicate.ContestRegistrationTransition {
	return predicate.ContestRegistrationTransition(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContestRegistrationTransition) predicate.ContestRegistrationTransition {
	return predicate.ContestRegistrationTransition(sql.NotPredicates(p))
}
